/**
 *  @author LuboJ
 *  @description Common parent for GraphLang.Math.Double nodes (C++ double, <cmath>; python float, math module).
 *  Each node only defines shape, ports and cppExpressionTemplate / pythonExpressionTemplate where {in1}, {in2} are replaced
 *  by wire names connected to input ports. Result is assigned to every wire connected to out1.
 *  Generated by GraphLang double math nodes generator.
 */
GraphLang.Math.Double.CommonParent = GraphLang.UserDefinedNode.extend({
    NAME: "GraphLang.Math.Double.CommonParent",

    init:function(attr, setter, getter)
    {
        this._super( $.extend({stroke:0, bgColor:null, width: 100, height: 50},attr), setter, getter);
    },

   applyAlpha: function()
   {
   },

   layerGet: function(name, attributes)
   {
      if(this.svgNodes===null) return null;
      var result=null;
      this.svgNodes.some(function(shape){
         if(shape.data("name")===name){
            result=shape;
         }
         return result!==null;
      });
      return result;
   },

   layerAttr: function(name, attributes)
   {
     if(this.svgNodes===null) return;
     this.svgNodes.forEach(function(shape){
             if(shape.data("name")===name){
                  shape.attr(attributes);
             }
     });
   },

   layerShow: function(name, flag, duration)
   {
      if(this.svgNodes===null) return;
      this.svgNodes.forEach(function(node){
          if(node.data("name")===name){
               if(flag){node.show();}
               else{node.hide();}
           }
       });
   },

    getParameterSettings: function()
    {
        return [];
    },

    addPort: function(port, locator)
    {
        this._super(port, locator);
        return port;
    },

    getPersistentAttributes : function()
    {
        var memento = this._super();
        memento.labels = [];
        this.children.each(function(i,e){
            var labelJSON = e.figure.getPersistentAttributes();
            labelJSON.locator=e.locator.NAME;
            memento.labels.push(labelJSON);
        });
        return memento;
    },

    setPersistentAttributes : function(memento)
    {
        this._super(memento);
        this.resetChildren();
        $.each(memento.labels, $.proxy(function(i,json){
            var figure =  eval("new "+json.type+"()");
            figure.attr(json);
            var locator =  eval("new "+json.locator+"()");
            this.add(figure, locator);
        },this));
    },

    /**
     * @method translateExpressionToCode
     * @param {string} expressionTemplate
     * @param {string} language - "cpp" or "python"
     * @returns {string} code, each line ends with \n
     */
    translateExpressionToCode: function(expressionTemplate, language){
        let code = "";
        let comment = (text) => language == "python" ? `# ${text}\n` : `/* ${text} */\n`;
        let lineEnd = language == "python" ? "\n" : ";\n";

        let expression = expressionTemplate;
        let missingInputs = [];
        this.getInputPorts().each((portIndex, portObj) => {
            let portName = portObj.getName();
            if (portObj.getConnections().getSize() > 0){
                expression = expression.replaceAll(`{${portName}}`, portObj.getConnections().first().getVariableName());
            }else{
                missingInputs.push(portName);
            }
        });
        if (missingInputs.length > 0){
            return comment(`ERROR: ${this.NAME} input ${missingInputs.join(", ")} not connected, no code generated`);
        }

        let outPort = this.getOutputPort("out1");
        if (outPort.getConnections().getSize() == 0){
            return comment(`MISSING OUTPUT WIRES CONNECTED TO ${this.NAME} OUTPUT, NO CODE GENERATED`);
        }
        outPort.getConnections().each((connIndex, connObj) => {
            code += connObj.getVariableName() + " = " + expression + lineEnd;
        });
        return code;
    },

    translateToCppCodeImport: function(){
        return "#include <cmath>";
    },

    translateToPythonCodeImport: function(){
        return "import math";
    },

    translateToCppCode: function(){
        return this.translateExpressionToCode(this.cppExpressionTemplate, "cpp");
    },

    translateToPythonCode: function(){
        return this.translateExpressionToCode(this.pythonExpressionTemplate, "python");
    },
});
